function extractFirstJsonObject(text) {
  const s = String(text || '')
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  const start = s.indexOf('{');
  if (start === -1) {
    throw new Error('No JSON object start found in AI output');
  }

  let depth = 0;
  let inString = false;
  let escaped = false;

  for (let i = start; i < s.length; i++) {
    const ch = s[i];

    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (ch === '\\') {
        escaped = true;
      } else if (ch === '"') {
        inString = false;
      }
      continue;
    }

    if (ch === '"') {
      inString = true;
      continue;
    }

    if (ch === '{') depth++;
    if (ch === '}') depth--;

    if (depth === 0) {
      return {
        jsonText: s.slice(start, i + 1),
        trailingText: s.slice(i + 1).trim(),
        cleanedText: s,
      };
    }
  }

  throw new Error('Could not find a complete JSON object in AI output');
}

return items.map(item => {
  const raw = item.json.output ?? item.json.text ?? item.json.response ?? '';
  const extracted = extractFirstJsonObject(raw);
  const parsed = JSON.parse(extracted.jsonText);

  return {
    json: {
      ...parsed,
      _debug_trailing_text: extracted.trailingText || null,
    },
  };
});

