// Punchy + marketing-forward title optimizer for Blaze + AIOSEO

function parseObject(val) {
  if (!val) return {};
  if (typeof val === 'string') {
    try { return JSON.parse(val); } catch (e) { return {}; }
  }
  return val;
}

function capFirst(str) {
  if (!str) return '';
  return str.charAt(0).toUpperCase() + str.slice(1);
}

function titleCase(str) {
  if (!str) return '';
  return str
    .split(' ')
    .filter(Boolean)
    .map(w => w[0].toUpperCase() + w.slice(1))
    .join(' ');
}

function getAudienceFromPersona(personaRaw) {
  const persona = (personaRaw || '').toLowerCase();

  if (persona.includes('seller')) return 'Sellers';
  if (persona.includes('owner')) return 'Owners';
  if (persona.includes('landlord')) return 'Owners';
  if (persona.includes('investor')) return 'Investors';
  if (persona.includes('buyer')) return 'Buyers';
  if (persona.includes('tenant') || persona.includes('renter')) return 'Renters';

  return 'Homeowners';
}

function ensureTexasInKeyword(keyword) {
  if (!keyword) return '';
  const lower = keyword.toLowerCase();
  if (lower.includes('texas')) return keyword;
  // tack "in Texas" at the end if it's not already there
  return keyword + ' in Texas';
}

function normalizeFocusKeyword(seo) {
  // try several spots
  return (
    seo.seo_focus_keyword ||
    seo.focus_keyword      ||
    seo.focusKeyword      ||
    ''
  );
}

function buildOptions(focusKeywordRaw, audience) {
  let fk = focusKeywordRaw.trim();
  if (!fk) return [];

  // Make sure Texas context is there
  fk = ensureTexasInKeyword(fk);

  // Ensure leading capital
  const fkLead = capFirst(fk);

  const options = [];

  // Option 1 – primary, very punchy
  options.push(`${fkLead}: What Every ${audience} MUST Know`);

  // Option 2 – tension / overlooked angle
  options.push(`${fkLead}: What Most ${audience} Overlook`);

  // Option 3 – checklist framing
  options.push(`${fkLead}: The Critical ${audience} Checklist`);

  return options;
}

const items = $input.all();

return items.map(item => {
  const json = item.json || {};

  const seo = parseObject(json.seo);
  const persona = seo.persona || json.persona || null;

  const audience = getAudienceFromPersona(persona);
  const focusKeywordRaw = normalizeFocusKeyword(seo);

  let options = buildOptions(focusKeywordRaw, audience);

  // Fallbacks if something is weird
  if (!options.length) {
    const base =
      seo.title ||
      seo.seo_title ||
      json.title ||
      'Real Estate Tips for the Texas Panhandle';

    const cleanBase = base.replace(/\s*\|\s*Blaze Real Estate.*/i, '').trim();

    options = [
      `${cleanBase}: What Every ${audience} MUST Know`,
      `${cleanBase}: The Critical ${audience} Guide`,
      `${cleanBase}: Proven Tips for ${audience}`
    ];
  }

  const primaryTitle = options[0];
  const altTitle1    = options[1] || null;
  const altTitle2    = options[2] || null;

  // Update seo object so downstream nodes (and SQL) see the new title
  seo.seo_title = primaryTitle;

  return {
    json: {
      ...json,
      // keep seo as JSON string if that's how your next Set node expects it
      seo,
      title: primaryTitle,        // <- use this in your WP Create Post node
      seo_title: primaryTitle,    // <- for AIOSEO/SQL if needed
      alt_title_1: altTitle1,
      alt_title_2: altTitle2
    }
  };
});

